const CACHE='finrate-lite-c7a28b49ec82';const ASSETS=["./app.css","./app.js","./apple-touch-icon.png","./icon-192.png","./icon-512.png","./index.html","./manifest.webmanifest"];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));});self.addEventListener('activate',e=>{e.waitUntil(Promise.all([caches.keys().then(k=>Promise.all(k.filter(x=>x.startsWith('finrate-lite-')&&x!==CACHE).map(x=>caches.delete(x)))),self.clients.claim()]));});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match(new URL('./index.html',self.registration.scope).href).then(x=>x||fetch(e.request)):fetch(e.request))));});